import React from 'react';
import ProcessCard from './ProcessCard';
import Grid from '@mui/material/Grid';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box'; // For placeholder message styling

const ProcessGrid = ({ processes }) => {
  if (!processes || processes.length === 0) {
    return (
      <Box sx={{ textAlign: 'center', mt: 4, mb: 4 }}>
        <Typography variant="subtitle1" color="text.secondary">
          No processes found. Click "Create New Process" to get started!
        </Typography>
      </Box>
    );
  }

  return (
    <Grid container spacing={3} sx={{ mt: 1, mb: 2 }}> {/* Added some top/bottom margin */}
      {processes.map(process => (
        <Grid item key={process.id} xs={12} sm={6} md={4} lg={3}> {/* Responsive item sizing */}
          <ProcessCard process={process} />
        </Grid>
      ))}
    </Grid>
  );
};

export default ProcessGrid;
